// Generated by aistatus — do not edit by hand.
// Re-run: aistatus install-hooks --agent opencode
//
// opencode v2 TUI (client) plugin. It runs in the local terminal client, so it
// sees what the CLI has open (`ui.tabs`/`ui.router`) and the event stream of the
// server that client is connected to — including a *remote* server. Local
// sessions are already reported by the server-side plugin (plugins/aistatus.js),
// so this plugin only reports sessions that live on a remote server AND are
// currently open in this client.
import { Plugin } from "@opencode/plugin/tui"
import { spawn } from "node:child_process"
import fs from "node:fs"
import path from "node:path"

const PY = __PY__
const AI_STATUS_HOME = __AI_STATUS_HOME__
const LOCAL_PREFIX = __LOCAL_HOME__        // e.g. "/Users/liuzixiang"
const REMOTE_LABEL = __REMOTE_LABEL__      // shown as "<label> · <session title>"
const LOG = path.join(AI_STATUS_HOME, "tui-plugin.log")
const BLOCKED = path.join(AI_STATUS_HOME, "blocked.json")
const HOOK_TIMEOUT_MS = 8000

let blockedCache = { at: 0, set: new Set() }
function isBlocked(sid) {
  const now = Date.now()
  if (now - blockedCache.at > 2000) {
    let set = new Set()
    try { set = new Set(Object.keys(JSON.parse(fs.readFileSync(BLOCKED, "utf8")) || {})) } catch (e) {}
    blockedCache = { at: now, set }
  }
  return blockedCache.set.has(sid)
}

function log(line) {
  try {
    fs.mkdirSync(AI_STATUS_HOME, { recursive: true })
    fs.appendFileSync(LOG, new Date().toISOString() + "  " + line + "\n")
  } catch (e) {}
}

function safeStringify(value) {
  try { return JSON.stringify(value) } catch (e) {
    try {
      const seen = new Set()
      return JSON.stringify(value, (k, v) => {
        if (typeof v === "object" && v !== null) { if (seen.has(v)) return undefined; seen.add(v) }
        return v
      })
    } catch (e2) { return "{}" }
  }
}

// A session is "remote" when its directory is outside the local home prefix.
// (A local macOS session is always under e.g. /Users/<user>/…)
function isRemoteDir(dir) {
  return typeof dir === "string" && dir.length > 0 && !dir.startsWith(LOCAL_PREFIX)
}

function forward(eventType, data, name, dir, created) {
  const sid = data?.sessionID ?? data?.form?.sessionID ?? null
  if (!sid || isBlocked(sid)) return
  const label = (REMOTE_LABEL && name) ? REMOTE_LABEL + " · " + name : name
  const payload = safeStringify({
    session_id: sid,
    session_name: label ?? null,
    session_dir: dir ?? null,
    session_host: "com.microsoft.VSCode",
    session_ref: null,
    message: null,
    seq: created ?? Date.now(),
    event: eventType,
    v2raw: true,
    properties: data ?? {},
  })
  let child
  try {
    child = spawn(PY, ["-m", "aistatus", "hook", "--agent", "opencode", "--default-state", "", "--verbose"], {
      env: { ...process.env, AISTATUS_HOME: AI_STATUS_HOME },
      stdio: ["pipe", "ignore", "pipe"],
    })
  } catch (e) { log(`hook spawn threw ${eventType}: ${e}`); return }
  let err = ""
  let done = false
  const finish = (reason) => {
    if (done) return
    done = true
    clearTimeout(timer)
    const msg = err.trim()
    if (reason || msg) log(`hook ${reason ?? "ok"} ${eventType}${msg ? " :: " + msg.split("\n").slice(-2).join(" | ") : ""}`)
  }
  const timer = setTimeout(() => { try { child.kill("SIGKILL") } catch (e) {} ; finish("timeout") }, HOOK_TIMEOUT_MS)
  child.stderr.on("data", (d) => { err += d.toString() })
  child.on("error", (e) => { err += String(e); finish("spawn-error") })
  child.on("exit", (code) => finish(code ? "exit=" + code : null))
  try { child.stdin.end(payload) } catch (e) { err += String(e); finish("stdin-error") }
}

// Only the state-changing V2 events (the high-frequency deltas are ignored).
const HANDLED = /^(session\.(execution\.(started|succeeded|failed|interrupted)|reasoning\.started|error|created|updated|renamed|tool\.(called|success|failed))|permission\.(asked|replied)|form\.(created|replied|cancelled))$/

export default Plugin.define({
  id: "aistatus.tui",
  setup(context) {
    log("tui plugin loaded loc=" + JSON.stringify(context?.location?.directory ?? null))
    const openIds = () => {
      const ids = new Set()
      try { for (const t of context?.ui?.tabs?.list?.() ?? []) if (t?.sessionID) ids.add(t.sessionID) } catch (e) {}
      try {
        const r = context?.ui?.router?.current?.()
        if (r?.type === "session" && r.sessionID) ids.add(r.sessionID)
      } catch (e) {}
      return ids
    }
    const titleOf = (sid) => {
      try { for (const t of context?.ui?.tabs?.list?.() ?? []) if (t?.sessionID === sid) return t.title } catch (e) {}
      return null
    }
    const stop = context.data.listen((arg) => {
      const d = arg?.details ?? arg
      const type = d?.type
      if (!type || !HANDLED.test(type)) return
      const dir = d?.location?.directory
      if (!isRemoteDir(dir)) return              // local sessions → server plugin
      const data = d?.data ?? {}
      const sid = data?.sessionID ?? data?.form?.sessionID ?? d?.durable?.aggregateID
      if (!sid) return
      if (!openIds().has(sid)) return            // only sessions open in THIS client
      forward(type, data, titleOf(sid), dir, d?.created)
    })
    return () => { try { stop() } catch (e) {} }
  },
})
